/**
 * Where attachment bytes live. Locally they are files under the data folder; on AWS the same
 * interface is backed by S3 (added with the production stack in phase 5).
 */
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, join, resolve } from 'node:path'

export interface FileStore {
  put(key: string, bytes: Buffer, contentType: string): Promise<void>
  get(key: string): Promise<Buffer | null>
}

/** Keys are generated by the API (team/item/uuid), never taken from the person. */
export function diskFileStore(root: string): FileStore {
  const base = resolve(root)
  const pathOf = (key: string) => {
    const path = resolve(join(base, key))
    if (!path.startsWith(base)) throw new Error('bad storage key')
    return path
  }
  return {
    async put(key, bytes) {
      const path = pathOf(key)
      await mkdir(dirname(path), { recursive: true })
      await writeFile(path, bytes)
    },
    async get(key) {
      try {
        return await readFile(pathOf(key))
      } catch {
        return null
      }
    },
  }
}

/** For tests: keeps files in memory. */
export function memoryFileStore(): FileStore {
  const files = new Map<string, Buffer>()
  return {
    async put(key, bytes) {
      files.set(key, bytes)
    },
    async get(key) {
      return files.get(key) ?? null
    },
  }
}

/** Pictures, documents, PDFs and spreadsheets (WP-BRIEF-002). */
export const ALLOWED_TYPES = new Set([
  'image/png',
  'image/jpeg',
  'image/gif',
  'image/webp',
  'application/pdf',
  'text/plain',
  'text/csv',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.ms-excel',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'application/vnd.ms-powerpoint',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation',
])

/** Amazon S3, used on AWS. The bucket blocks public access; the API streams files to people. */
export async function s3FileStore(bucket: string): Promise<FileStore> {
  const { S3Client, GetObjectCommand, PutObjectCommand } = await import('@aws-sdk/client-s3')
  const client = new S3Client({})
  return {
    async put(key, bytes, contentType) {
      await client.send(
        new PutObjectCommand({ Bucket: bucket, Key: key, Body: bytes, ContentType: contentType }),
      )
    },
    async get(key) {
      try {
        const out = await client.send(new GetObjectCommand({ Bucket: bucket, Key: key }))
        return out.Body ? Buffer.from(await out.Body.transformToByteArray()) : null
      } catch {
        return null
      }
    },
  }
}
